arguments.content:
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; height: 100vh; display: flex; background: #f5f5f5; color: #333; }
#app { display: flex; width: 100%; height: 100%; }

/* Sidebar */
#sidebar { width: 260px; background: #1e1e2e; color: #cdd6f4; display: flex; flex-direction: column; flex-shrink: 0; }
.sidebar-header { display: flex; align-items: center; justify-content: space-between; padding: 16px; border-bottom: 1px solid #313244; }
.sidebar-header h2 { font-size: 16px; font-weight: 600; }
#new-note-btn { background: #89b4fa; border: none; color: #1e1e2e; width: 28px; height: 28px; border-radius: 6px; font-size: 18px; cursor: pointer; font-weight: bold; }
#new-note-btn:hover { background: #b4d0fb; }
#search { margin: 8px 12px; padding: 8px 12px; border-radius: 6px; border: 1px solid #313244; background: #313244; color: #cdd6f4; font-size: 13px; outline: none; }
#search:focus { border-color: #89b4fa; }
#note-list { list-style: none; overflow-y: auto; flex: 1; }
#note-list li { padding: 10px 16px; cursor: pointer; font-size: 13px; border-bottom: 1px solid #313244; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#note-list li:hover { background: #313244; }
#note-list li.active { background: #45475a; color: #89b4fa; }

/* Editor area */
#editor-area { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.toolbar { display: flex; align-items: center; justify-content: space-between; padding: 8px 16px; background: #fff; border-bottom: 1px solid #e0e0e0; }
#note-title { font-size: 18px; font-weight: 600; outline: none; border: none; padding: 4px 8px; border-radius: 4px; min-width: 100px; }
#note-title:empty::before { content: attr(data-placeholder); color: #aaa; }
#delete-btn { background: none; border: none; font-size: 18px; cursor: pointer; padding: 4px 8px; border-radius: 4px; }
#delete-btn:hover { background: #fee; color: #e55; }

/* Split pane */
.split-pane { display: flex; flex: 1; overflow: hidden; }
#editor { flex: 1; resize: none; border: none; padding: 16px; font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace; font-size: 14px; line-height: 1.6; outline: none; background: #fff; tab-size: 2; }
#preview { flex: 1; padding: 16px; overflow-y: auto; background: #fff; border-left: 1px solid #e0e0e0; }

/* Markdown preview styling */
.markdown-body { font-size: 14px; line-height: 1.7; }
.markdown-body h1 { font-size: 1.8em; margin: 0.4em 0; border-bottom: 1px solid #eee; padding-bottom: 0.3em; }
.markdown-body h2 { font-size: 1.4em; margin: 0.4em 0; }
.markdown-body h3 { font-size: 1.2em; margin: 0.3em 0; }
.markdown-body code { background: #f0f0f0; padding: 2px 6px; border-radius: 3px; font-size: 0.9em; }
.markdown-body pre { background: #f6f8fa; padding: 12px; border-radius: 6px; overflow-x: auto; margin: 8px 0; }
.markdown-body pre code { background: none; padding: 0; }
.markdown-body blockquote { border-left: 3px solid #89b4fa; margin: 8px 0; padding: 4px 16px; color: #666; }
.markdown-body ul, .markdown-body ol { padding-left: 24px; margin: 8px 0; }
.markdown-body a { color: #89b4fa; }
.markdown-body img { max-width: 100%; }
.markdown-body table { border-collapse: collapse; margin: 8px 0; }
.markdown-body th, .markdown-body td { border: 1px solid #ddd; padding: 6px 12px; }
.markdown-body th { background: #f6f8fa; }

(() => {
  const STORAGE_KEY = 'markdown-notes';
  let notes = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  let activeId = null;

  const $ = id => document.getElementById(id);
  const editor = $('editor');
  const preview = $('preview');
  const noteTitle = $('note-title');
  const noteList = $('note-list');
  const searchInput = $('search');

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
  }

  function renderList(filter = '') {
    const q = filter.toLowerCase();
    const filtered = notes.filter(n => n.title.toLowerCase().includes(q) || n.body.toLowerCase().includes(q))
      .sort((a, b) => b.updated - a.updated);
    noteList.innerHTML = '';
    filtered.forEach(n => {
      const li = document.createElement('li');
      li.textContent = n.title || 'Untitled Note';
      if (n.id === activeId) li.classList.add('active');
      li.onclick = () => selectNote(n.id);
      noteList.appendChild(li);
    });
  }

  function selectNote(id) {
    // Save current before switching
    if (activeId) commitCurrent();
    activeId = id;
    const note = notes.find(n => n.id === id);
    if (!note) return;
    noteTitle.textContent = note.title;
    editor.value = note.body;
    renderPreview();
    renderList(searchInput.value);
  }

  function commitCurrent() {
    if (!activeId) return;
    const note = notes.find(n => n.id === activeId);
    if (!note) return;
    note.title = noteTitle.textContent.trim() || 'Untitled Note';
    note.body = editor.value;
    note.updated = Date.now();
    save();
  }

  function renderPreview() {
    preview.innerHTML = marked.parse(editor.value || '*Start writing…*');
  }

  function createNote() {
    const note = { id: crypto.randomUUID(), title: '', body: '', created: Date.now(), updated: Date.now() };
    notes.unshift(note);
    save();
    selectNote(note.id);
    editor.focus();
  }

  function deleteNote() {
    if (!activeId) return;
    if (!confirm('Delete this note?')) return;
    notes = notes.filter(n => n.id !== activeId);
    save();
    activeId = null;
    if (notes.length) selectNote(notes[0].id);
    else { noteTitle.textContent = ''; editor.value = ''; preview.innerHTML = ''; }
    renderList(searchInput.value);
  }

  // Debounced input handling
  let debounce;
  editor.addEventListener('input', () => {
    renderPreview();
    clearTimeout(debounce);
    debounce = setTimeout(() => { commitCurrent(); renderList(searchInput.value); }, 300);
  });

  noteTitle.addEventListener('input', () => {
    clearTimeout(debounce);
    debounce = setTimeout(() => { commitCurrent(); renderList(searchInput.value); }, 300);
  });

  // Tab support in editor
  editor.addEventListener('keydown', e => {
    if (e.key === 'Tab') {
      e.preventDefault();
      const s = editor.selectionStart, end = editor.selectionEnd;
      editor.value = editor.value.substring(0, s) + '  ' + editor.value.substring(end);
      editor.selectionStart = editor.selectionEnd = s + 2;
      editor.dispatchEvent(new Event('input'));
    }
  });

  searchInput.addEventListener('input', () => renderList(searchInput.value));
  $('new-note-btn').addEventListener('click', createNote);
  $('delete-btn').addEventListener('click', deleteNote);

  // Init
  if (notes.length) selectNote(notes[0].id);
  else renderList();
})();
